    final long token = com.android.systemui.hecker.HeckerAmbientCharging.pulseGeneration();
    if (mMachine.isExecutingTransition()) {
        com.android.systemui.hecker.HeckerAmbientCharging.retryPulse();
        return;
    }
    final State state = mMachine.getState();
    if (state == State.INITIALIZED || state == State.UNINITIALIZED
            || state == State.DOZE_REQUEST_PULSE || state == State.DOZE_PULSE_DONE
            || mDozeHost.isPulsePending()) {
        com.android.systemui.hecker.HeckerAmbientCharging.retryPulse();
        return;
    }
    if (state == State.DOZE_PULSING || state == State.DOZE_PULSING_BRIGHT) {
        mDozeHost.extendPulse(DozeLog.PULSE_REASON_INTENT);
        com.android.systemui.hecker.HeckerAmbientCharging.pulseAccepted(token);
        return;
    }
    // Let native proximity, power saving, provisioning and pulse eligibility decide.
    requestPulse(DozeLog.PULSE_REASON_INTENT, false,
            () -> com.android.systemui.hecker.HeckerAmbientCharging.pulseSuppressed(token));
    com.android.systemui.hecker.HeckerAmbientCharging.pulseAccepted(token);
}

